from bagimlilik import kurulum_sirasi, DonguHatasi

# Test 1: Kendine bağımlılık döngüsü
deps1 = {"a": ["a"]}
try:
    sira1 = kurulum_sirasi(deps1)
    print("Test 1 HATA: Döngü yakalanmadı")
except DonguHatasi as e:
    print("Test 1 Döngü:", e.dongu)
    assert e.dongu == ["a"], f"Beklenen ['a'], alına {e.dongu}"

# Test 2: 3'lü döngü a->b->c->a (b a'ya, c b'ye, a c'ye bağımlı)
deps2 = {"b": ["a"], "c": ["b"], "a": ["c"]}
try:
    sira2 = kurulum_sirasi(deps2)
    print("Test 2 HATA: Döngü yakalanmadı")
except DonguHatasi as e:
    print("Test 2 Döngü:", e.dongu)
    # ["a", "b", "c"] olmalı (alfabetik en küçük ile başla)
    assert e.dongu == ["a", "b", "c"], f"Beklenen ['a', 'b', 'c'], alına {e.dongu}"

# Test 3: 4'lü döngü a->b->c->d->a
deps3 = {"b": ["a"], "c": ["b"], "d": ["c"], "a": ["d"]}
try:
    sira3 = kurulum_sirasi(deps3)
    print("Test 3 HATA: Döngü yakalanmadı")
except DonguHatasi as e:
    print("Test 3 Döngü:", e.dongu)
    # ["a", "b", "c", "d"] olmalı
    assert e.dongu == ["a", "b", "c", "d"], f"Beklenen ['a', 'b', 'c', 'd'], alına {e.dongu}"

# Test 4: Karma döngü (2 döngülü bileşen)
deps4 = {"a": ["b"], "b": ["a"], "c": ["d"], "d": ["c"]}
try:
    sira4 = kurulum_sirasi(deps4)
    print("Test 4 HATA: Döngü yakalanmadı")
except DonguHatasi as e:
    print("Test 4 Döngü:", e.dongu)
    # ["a", "b"] veya ["c", "d"] olmalı, alfabetik en küçük paketten başlayan döngü
    assert set(e.dongu) == {"a", "b"}, f"Beklenen döngü {'a' ve 'b'}, alına {e.dongu}"

print("Döngü testleri geçti!")

